components.css:
.ds-button-primary { font: 14px/1.65 var(--font-ui, system-ui, "Microsoft YaHei", "PingFang SC", "Noto Sans CJK SC", sans-serif); display: inline-flex; align-items: center; justify-content: center; min-height: 36px; padding: 5px 12px; border: 1px solid var(--color-accent, #166557); border-radius: var(--control-radius, 6px); background: var(--color-accent, #166557); color: var(--color-surface, #ffffff); line-height: 1.4; font-weight: 620; cursor: pointer; }
.ds-button-primary:hover:not(:disabled) { background: var(--color-accent-hover, #0e4e44); color: var(--color-surface, #ffffff); border-color: var(--color-accent, #166557); }
.ds-button-primary:focus-visible { outline: 2px solid var(--color-focus, #146e60); outline-offset: 2px; }
.ds-button-primary:disabled { color: var(--color-text-secondary, #4b625d); opacity: .6; cursor: not-allowed; }
@media (max-width: 600px) { .ds-button-primary { min-height: 38px; } }

.ds-button-secondary { font: 14px/1.65 var(--font-ui, system-ui, "Microsoft YaHei", "PingFang SC", "Noto Sans CJK SC", sans-serif); display: inline-flex; align-items: center; justify-content: center; min-height: 36px; padding: 5px 12px; border: 1px solid var(--color-border, #cedbd5); border-radius: var(--control-radius, 6px); background: var(--color-surface, #ffffff); color: var(--color-text, #172c29); line-height: 1.4; font-weight: 400; cursor: pointer; }
.ds-button-secondary:hover:not(:disabled) { background: var(--color-accent-soft, #e0f2e9); color: var(--color-accent-hover, #0e4e44); border-color: var(--color-accent, #166557); }
.ds-button-secondary:focus-visible { outline: 2px solid var(--color-focus, #146e60); outline-offset: 2px; }
.ds-button-secondary:disabled { color: var(--color-text-secondary, #4b625d); opacity: .6; cursor: not-allowed; }
@media (max-width: 600px) { .ds-button-secondary { min-height: 38px; } }

.ds-button-ghost { font: 14px/1.65 var(--font-ui, system-ui, "Microsoft YaHei", "PingFang SC", "Noto Sans CJK SC", sans-serif); display: inline-flex; align-items: center; justify-content: center; min-height: 36px; padding: 5px 12px; border: 1px solid transparent; border-radius: var(--control-radius, 6px); background: transparent; color: var(--color-text, #172c29); line-height: 1.4; font-weight: 400; cursor: pointer; }
.ds-button-ghost:hover:not(:disabled) { background: var(--color-accent-soft, #e0f2e9); color: var(--color-accent-hover, #0e4e44); border-color: var(--color-accent, #166557); }
.ds-button-ghost:focus-visible { outline: 2px solid var(--color-focus, #146e60); outline-offset: 2px; }
.ds-button-ghost:disabled { color: var(--color-text-secondary, #4b625d); opacity: .6; cursor: not-allowed; }
@media (max-width: 600px) { .ds-button-ghost { min-height: 38px; } }

.ds-button-danger { font: 14px/1.65 var(--font-ui, system-ui, "Microsoft YaHei", "PingFang SC", "Noto Sans CJK SC", sans-serif); display: inline-flex; align-items: center; justify-content: center; min-height: 36px; padding: 5px 12px; border: 1px solid var(--color-border, #cedbd5); border-radius: var(--control-radius, 6px); background: var(--color-surface, #ffffff); color: var(--color-error, #a03636); line-height: 1.4; font-weight: 400; cursor: pointer; }
.ds-button-danger:hover:not(:disabled) { background: var(--color-error-soft, #fbeeee); color: var(--color-error, #a03636); border-color: var(--color-error, #a03636); }
.ds-button-danger:focus-visible { outline: 2px solid var(--color-focus, #146e60); outline-offset: 2px; }
.ds-button-danger:disabled { color: var(--color-text-secondary, #4b625d); opacity: .6; cursor: not-allowed; }
@media (max-width: 600px) { .ds-button-danger { min-height: 38px; } }

.ds-field { font: 14px/1.65 var(--font-ui, system-ui, "Microsoft YaHei", "PingFang SC", "Noto Sans CJK SC", sans-serif); display: inline-flex; flex-wrap: wrap; align-items: center; gap: 6px; font-size: .8125rem; color: var(--color-text-secondary, #4b625d); }
.ds-input { font: inherit; min-width: 0; max-width: 100%; min-height: 36px; padding: 6px 10px; border: 1px solid var(--color-border, #cedbd5); border-radius: var(--control-radius, 6px); background: var(--color-surface, #ffffff); color: var(--color-text, #172c29); caret-color: var(--color-accent, #166557); box-sizing: border-box; }
.ds-input::placeholder { color: var(--color-text-secondary, #4b625d); opacity: 1; }
.ds-input:focus-visible { outline: 2px solid var(--color-focus, #146e60); outline-offset: 2px; }
@media (max-width: 600px) { .ds-input { font-size: 1rem; } }

.ds-nav { font: 14px/1.65 var(--font-ui, system-ui, "Microsoft YaHei", "PingFang SC", "Noto Sans CJK SC", sans-serif); padding: 20px 12px 14px; background: var(--color-rail, #133b39); color: var(--color-rail-text, #f1faf6); }
.ds-nav-group { margin: 0 0 4px; padding-inline: 10px; color: var(--color-rail-muted, #bdd3cb); font-size: .75rem; font-weight: 600; }
.ds-nav-item { display: flex; align-items: center; gap: 10px; min-height: 36px; padding: 5px 10px; box-sizing: border-box; border-radius: var(--control-radius, 6px); color: var(--color-rail-text, #f1faf6); text-decoration: none; }
.ds-nav-icon { width: 18px; height: 18px; flex: none; fill: none; stroke: currentColor; stroke-width: 1.65; stroke-linecap: round; stroke-linejoin: round; }
.ds-nav-item:hover { color: var(--color-rail-text, #f1faf6); background: var(--color-rail-hover, #22534f); }
.ds-nav-item[aria-current="page"] { color: var(--color-rail, #133b39); background: var(--color-accent-soft, #e0f2e9); font-weight: 660; }
.ds-nav-item:focus-visible { outline: 2px solid var(--color-rail-text, #f1faf6); outline-offset: 2px; }
@media (max-width: 600px) { .ds-nav-item { min-height: 42px; } }

.ds-tag { font: 14px/1.65 var(--font-ui, system-ui, "Microsoft YaHei", "PingFang SC", "Noto Sans CJK SC", sans-serif); display: inline-flex; align-items: center; max-width: 100%; padding: 2px 7px; border-radius: 4px; font-size: .75rem; background: var(--color-subtle, #f5f8f6); color: var(--color-text-secondary, #4b625d); }
.ds-tag-ok { color: var(--color-success, #246342); background: var(--color-success-soft, #edf7ef); }
.ds-tag-warn { color: var(--color-warning, #785414); background: var(--color-warning-soft, #fff5df); }
.ds-tag-bad { color: var(--color-error, #a03636); background: var(--color-error-soft, #fbeeee); }

.ds-card { font: 14px/1.65 var(--font-ui, system-ui, "Microsoft YaHei", "PingFang SC", "Noto Sans CJK SC", sans-serif); padding: 18px; border: 1px solid var(--color-border, #cedbd5); border-radius: var(--radius, 12px); background: var(--color-surface, #ffffff); color: var(--color-text, #172c29); }
.ds-card-title { margin: 0 0 .5em; font-size: 1.125rem; line-height: 1.35; }
.ds-card-note { margin: 0 0 .75em; color: var(--color-text-secondary, #4b625d); }
@media (max-width: 600px) { .ds-card { padding: 14px; } }

.ds-composer { font: 14px/1.65 var(--font-ui, system-ui, "Microsoft YaHei", "PingFang SC", "Noto Sans CJK SC", sans-serif); border: 1px solid var(--color-border, #cedbd5); border-radius: var(--radius, 12px); background: var(--color-subtle, #f5f8f6); }
.ds-composer:focus-within { border-color: var(--color-accent, #166557); }
.ds-composer-input { box-sizing: border-box; display: block; width: 100%; padding: 12px 14px 4px; border: 0; border-radius: var(--radius, 12px); background: transparent; color: var(--color-text, #172c29); font: inherit; line-height: 1.65; resize: none; }
.ds-composer-input::placeholder { color: var(--color-text-secondary, #4b625d); opacity: 1; }
.ds-composer-input:focus-visible { outline: 2px solid var(--color-focus, #146e60); outline-offset: -2px; }
.ds-composer-actions { display: flex; justify-content: space-between; flex-wrap: wrap; align-items: center; gap: 6px; padding: 6px 10px 10px; }
.ds-composer-scope, .ds-composer-send { min-height: 32px; padding: 4px 10px; border: 1px solid var(--color-border, #cedbd5); border-radius: var(--control-radius, 6px); font: inherit; font-size: .8125rem; line-height: 1.4; cursor: pointer; }
.ds-composer-scope { background: var(--color-surface, #ffffff); color: var(--color-text, #172c29); }
.ds-composer-scope:hover { background: var(--color-accent-soft, #e0f2e9); border-color: var(--color-accent, #166557); color: var(--color-accent-hover, #0e4e44); }
.ds-composer-send { background: var(--color-accent, #166557); border-color: var(--color-accent, #166557); color: var(--color-surface, #ffffff); font-weight: 620; }
.ds-composer-send:hover { background: var(--color-accent-hover, #0e4e44); }
.ds-composer-scope:focus-visible { outline: 2px solid var(--color-focus, #146e60); outline-offset: 2px; }
.ds-composer-send:focus-visible { outline: 2px solid var(--color-focus, #146e60); outline-offset: 2px; }
@media (max-width: 600px) { .ds-composer-input { font-size: 1rem; } .ds-composer-actions { padding-inline: 6px; } .ds-composer-scope, .ds-composer-send { min-height: 38px; padding-inline: 6px; } }

.ds-index { font: 14px/1.65 var(--font-ui, system-ui, "Microsoft YaHei", "PingFang SC", "Noto Sans CJK SC", sans-serif); background: var(--color-subtle, #f5f8f6); color: var(--color-text, #172c29); padding: 14px 16px; border-radius: var(--radius, 12px); }
.ds-index-title { display: block; font-size: .9375rem; margin-bottom: 8px; }
.ds-index-row { display: flex; justify-content: space-between; align-items: baseline; gap: 8px; padding: 6px 3px; border-bottom: 1px solid var(--color-border, #cedbd5); color: var(--color-text, #172c29); text-decoration: none; }
.ds-index-row b { font-variant-numeric: tabular-nums; }
.ds-index-row:hover { color: var(--color-accent-hover, #0e4e44); background: var(--color-accent-soft, #e0f2e9); }
.ds-index-row:focus-visible { outline: 2px solid var(--color-focus, #146e60); outline-offset: 2px; }
